import React from 'react';
import { graphql } from 'gatsby';
import PropTypes from 'prop-types';
import { Layout, Hero, About, Jobs, Education, Skills, Featured, Contact } from '@components';
import styled from 'styled-components';
import { Main } from '@styles';
import skillOrder from '../../content/skills/sde/skillOrder.json';
import projectOrder from '../../content/featured/sde/projectOrder.json';

const StyledMainContainer = styled(Main)`
  counter-reset: section;
`;

const SdeProfilePage = ({ location, data }) => {
  return (
    <Layout location={location}>
      <StyledMainContainer className="fillHeight">
        <Hero data={data.hero.edges} />
        <About data={data.about.edges} />
        <Jobs data={data.jobs.edges} />
        <Education data={data.education.edges} />
        {/* <Featured data={data.featured.edges} /> */}
        <Featured data={data.featured.edges} projectOrder={projectOrder} />
        {/* {data.projects && <Projects data={data.projects.edges} />} */}
        <Skills skillsData={data.skills.edges} skillOrder={skillOrder} />
        {/* {data.certifications && <Certifications data={data.certifications.edges} />} */}
        <Contact data={data.contact.edges} />
      </StyledMainContainer>
    </Layout>
  );
};

SdeProfilePage.propTypes = {
  location: PropTypes.shape({
    pathname: PropTypes.string.isRequired,
  }).isRequired,
  data: PropTypes.shape({
    hero: PropTypes.object.isRequired,
    about: PropTypes.object.isRequired,
    jobs: PropTypes.object.isRequired,
    education: PropTypes.object.isRequired,
    featured: PropTypes.object.isRequired,
    projects: PropTypes.object,
    certifications: PropTypes.object,
    skills: PropTypes.object.isRequired,
    contact: PropTypes.object.isRequired,
  }).isRequired,
};

export default SdeProfilePage;

export const sdeProfilePageQuery = graphql`
  {
    hero: allMarkdownRemark(filter: { fileAbsolutePath: { regex: "/hero/sde/" } }) {
      edges {
        node {
          frontmatter {
            title
            name
            subtitle
            buttonText
          }
          html
        }
      }
    }

    about: allMarkdownRemark(filter: { fileAbsolutePath: { regex: "/about/sde/" } }) {
      edges {
        node {
          frontmatter {
            title
            avatar {
              childImageSharp {
                gatsbyImageData(
                  width: 700
                  quality: 90
                  placeholder: DOMINANT_COLOR
                  layout: CONSTRAINED
                )
              }
            }
            skills
          }
          html
        }
      }
    }

    jobs: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/jobs/" }
        frontmatter: { showInExperience: { eq: true } }
      }
      sort: {frontmatter: {date: DESC}}
    ) {
      edges {
        node {
          frontmatter {
            title
            company
            shortname
            location
            range
            url
            tech
            logo {
              childImageSharp {
              gatsbyImageData(
                width: 700
                quality: 90
                placeholder: DOMINANT_COLOR
                layout: CONSTRAINED
              )
            }
            }
          }
          html
        }
      }
    }

    education: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/education/" }
        frontmatter: { showInEducation: { eq: true } }
      }
      sort: {frontmatter: {date: DESC}}
    ) {
      edges {
        node {
          frontmatter {
            school
            shortname
            programme
            score
            location
            range
            url
            logo{
              childImageSharp {
              gatsbyImageData(
                width: 700
                quality: 90
                placeholder: DOMINANT_COLOR
                layout: CONSTRAINED
              )
            }
            }
          }
          html
        }
      }
    }

    featured: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/featured/sde/" }
        frontmatter: { showInFeatured: { eq: true } }
      }
    ) {
      edges {
        node {
          frontmatter {
            title
            imageCarousel {
              childImageSharp {
                gatsbyImageData(
                  width: 700
                  quality: 90
                  placeholder: DOMINANT_COLOR
                  layout: CONSTRAINED
                )
              }
            }
            gifCarousel
            tech
            github
            drive
            external
            youtube
            tags
          }
          html
        }
      }
    }

    projects: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/featured/sde/" }
        frontmatter: { showInProjects: { eq: true }, showInFeatured: { eq: false } }
      }
      sort: {frontmatter: {date: DESC}}
    ) {
      edges {
        node {
          frontmatter {
            title
            tech
            github
            external
          }
          html
        }
      }
    }

    certifications: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/certifications/sde/" }
        frontmatter: { showInCertifications: { eq: true } }
      }
      sort: {frontmatter: {priority: ASC}}
    ) {
      edges {
        node {
          frontmatter {
            course
            institute
            company
            github
            external
            tech
          }
          html
        }
      }
    }

    skills: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/skills/types/" }
        frontmatter: { showInSkills: { eq: true } }
      }
    ) {
      edges {
        node {
          frontmatter {
            name
            logo {
              childImageSharp {
                gatsbyImageData(
                  width: 700
                  quality: 90
                  placeholder: DOMINANT_COLOR
                  layout: CONSTRAINED
                )
              }
            }
          }
          html
        }
      }
    }

    contact: allMarkdownRemark(filter: { fileAbsolutePath: { regex: "/contact/" } }) {
      edges {
        node {
          frontmatter {
            title
            buttonText
          }
          html
        }
      }
    }
  }
`;
